const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define southern Siberia region
  const southernSiberia = ee.Geometry.Rectangle([85, 50, 110, 55]);

  // 2. Define dates
  const date1 = '2018-10-14';
  const date2 = '2018-10-29';

  // 3. Load MODIS Snow Cover data
  const modisSnow = ee.ImageCollection('MODIS/061/MOD10A1');

  // Get images for both dates
  const img1 = modisSnow.filterDate(date1, ee.Date(date1).advance(1, 'day'))
                        .filterBounds(southernSiberia)
                        .mosaic();

  const img2 = modisSnow.filterDate(date2, ee.Date(date2).advance(1, 'day'))
                        .filterBounds(southernSiberia)
                        .mosaic();

  // Check if collections have data
  const col1Size = modisSnow.filterDate(date1, ee.Date(date1).advance(1, 'day'))
                            .filterBounds(southernSiberia)
                            .size()
                            .getInfo();

  const col2Size = modisSnow.filterDate(date2, ee.Date(date2).advance(1, 'day'))
                            .filterBounds(southernSiberia)
                            .size()
                            .getInfo();

  console.log(`Oct 14 images: ${col1Size}, Oct 29 images: ${col2Size}`);

  if (col1Size === 0 || col2Size === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process snow cover (NDSI_Snow_Cover band, values 0-100)
  const snowBand = 'NDSI_Snow_Cover';

  // Create snow masks (snow >= 10% cover)
  const snow1 = img1.select(snowBand).gte(10);
  const snow2 = img2.select(snowBand).gte(10);

  // 5. Calculate snow-covered area
  const stats1 = snow1.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southernSiberia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = snow2.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southernSiberia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const snowPixels1 = stats1[snowBand + '_sum'];
  const totalPixels1 = stats1[snowBand + '_count'];
  const snowPixels2 = stats2[snowBand + '_sum'];
  const totalPixels2 = stats2[snowBand + '_count'];

  console.log(`Oct 14: Snow pixels=${snowPixels1}, Total=${totalPixels1}`);
  console.log(`Oct 29: Snow pixels=${snowPixels2}, Total=${totalPixels2}`);

  // 6. Validation
  if (totalPixels1 === 0 || totalPixels2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (snowPixels1 == null || snowPixels2 == null || 
      isNaN(snowPixels1) || isNaN(snowPixels2)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare snow cover
  const snowArea1 = snowPixels1;
  const snowArea2 = snowPixels2;

  console.log(`Snow area change: ${snowArea1} -> ${snowArea2}`);
  console.log(`Difference: ${snowArea2 - snowArea1} pixels`);

  if (snowArea2 > snowArea1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
